window.__SD=(window.__SD||[]).concat([{"slug": "paul-christiano", "name": "Paul Christiano", "category": "independent-org", "current_role": "Executive Director, Alignment Research Center (ARC) (since Aug 2026); OpenAI Foundation board member and Safety & Security Committee member (since Sept 2026); Senior Tech Advisor, US CAISI", "orgs_history": ["OpenAI, led language-model alignment team (2017-21)", "Founded ARC (2021)", "Head of AI Safety, US AI Safety Institute / CAISI at NIST (2024-26)", "Anthropic Long-Term Benefit Trust initial trustee (until 2024)"], "country": "United States", "known_for": "Co-inventor of RLHF and founder of ARC; one of the most respected technical alignment researchers", "bio": "Paul Christiano is an American AI alignment researcher. An IMO silver medallist, he studied mathematics at MIT (2012) and completed a PhD in theoretical computer science at UC Berkeley (2017), where he also worked with Katja Grace on AI Impacts. At OpenAI from 2017 to 2021 he led the language model alignment team and co-authored 'Deep Reinforcement Learning from Human Preferences', making him one of the principal architects of RLHF; he also helped develop scalable-oversight ideas such as AI safety via debate and iterated amplification. In 2021 he founded the Alignment Research Center (ARC), which spun out the model-evaluation group that became METR and now pursues mechanistic explanations of neural network behaviour. From 2024 he was head of AI safety at the US AI Safety Institute (now CAISI) in NIST. He returned to ARC as executive director in August 2026, and in September 2026 joined the OpenAI Foundation board and its Safety and Security Committee, saying the industry is not on track to reduce loss-of-control risk to an acceptable level.", "key_ideas": ["RLHF", "scalable oversight (debate, iterated amplification)", "eliciting latent knowledge", "mechanistic anomaly detection / heuristic explanations", "'What failure looks like' slow-takeover scenarios"], "key_works": [{"title": "Deep Reinforcement Learning from Human Preferences", "year": 2017, "url": "https://arxiv.org/abs/1706.03741"}, {"title": "AI safety via debate (with Geoffrey Irving and Dario Amodei)", "year": 2018, "url": "https://arxiv.org/abs/1805.00899"}, {"title": "What failure looks like", "year": 2019, "url": "https://www.alignmentforum.org/posts/HBxe6wdjxK239zajf/what-failure-looks-like"}, {"title": "My views on 'doom'", "year": 2023, "url": "https://www.lesswrong.com/posts/xWMqsvHapP3nwdSW8/my-views-on-doom"}, {"title": "Returning to ARC", "year": 2026, "url": "https://www.lesswrong.com/posts/vLFh8HP3hyNy9MCwe/returning-to-arc"}], "quotes": [{"text": "There is a meaningful risk that rapid acceleration in AI capabilities leads to catastrophic and irreversible loss of control in the very near term.", "context": "Statement on joining the OpenAI Foundation board, Sept 2026 (via The Guardian)", "source_url": "https://www.theguardian.com/technology/2026/sep/10/openai-risk-catastrophic-loss-control-board-member-paul-christiano"}, {"text": "I do not think that the AI industry in general, including OpenAI, is currently on track to reduce this risk to an acceptable level.", "context": "Statement on joining the OpenAI Foundation board, Sept 2026 (via The Guardian)", "source_url": "https://www.theguardian.com/technology/2026/sep/10/openai-risk-catastrophic-loss-control-board-member-paul-christiano"}, {"text": "Probability that most humans die within 10 years of building powerful AI (powerful enough to make human labor obsolete): 20%", "context": "'My views on doom', LessWrong, 2023", "source_url": "https://www.lesswrong.com/posts/xWMqsvHapP3nwdSW8/my-views-on-doom"}, {"text": "Probability of AI takeover: 22%", "context": "'My views on doom', LessWrong, 2023", "source_url": "https://www.lesswrong.com/posts/xWMqsvHapP3nwdSW8/my-views-on-doom"}, {"text": "machine learning will increase our ability to “get what we can measure,” which could cause a slow-rolling catastrophe.", "context": "'What failure looks like', Alignment Forum, 2019", "source_url": "https://www.alignmentforum.org/posts/HBxe6wdjxK239zajf/what-failure-looks-like"}], "interviews": [{"title": "Paul Christiano — Preventing an AI takeover", "outlet": "Dwarkesh Podcast", "year": 2023, "url": "https://www.dwarkesh.com/p/paul-christiano"}, {"title": "Paul Christiano on how OpenAI is developing real solutions to the 'AI alignment problem'", "outlet": "80,000 Hours Podcast", "year": 2018, "url": "https://80000hours.org/podcast/episodes/paul-christiano-ai-alignment-solutions/"}, {"title": "OpenAI not on track to reduce risk of 'catastrophic' loss of control, says board member", "outlet": "The Guardian", "year": 2026, "url": "https://www.theguardian.com/technology/2026/sep/10/openai-risk-catastrophic-loss-control-board-member-paul-christiano"}], "links": {"website": "https://paulfchristiano.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Paul_Christiano", "github": "", "substack": "https://ai-alignment.com/"}, "p_doom_or_stance": "2023 estimates: 22% probability of AI takeover; 20% that most humans die within 10 years of powerful AI; 46% that humanity irreversibly messes up its future within 10 years of powerful AI ('My views on doom'). Sept 2026: industry 'not on track' to reduce loss-of-control risk acceptably.", "honours": null, "photo": "paul-christiano.jpg"}, {"slug": "dan-hendrycks", "name": "Dan Hendrycks", "category": "independent-org", "current_role": "Director, Center for AI Safety (CAIS); safety adviser to xAI and adviser to Scale AI (as of 2025-26)", "orgs_history": ["PhD, UC Berkeley (2022)", "Founded/directs Center for AI Safety (2022-)", "xAI safety adviser ($1 salary, 2023-)", "Scale AI adviser (2024-)"], "country": "United States", "known_for": "Director of CAIS, organiser of the 2023 Statement on AI Risk, creator of MMLU, GELU and Humanity's Last Exam", "bio": "Dan Hendrycks is an American machine learning researcher and director of the Center for AI Safety (CAIS), a San Francisco nonprofit. Raised in Marshfield, Missouri, he earned a B.S. from the University of Chicago (2018) and a PhD in computer science from UC Berkeley (2022). He is lead author of the papers introducing the GELU activation function (2016) and the MMLU benchmark (2020), and created Humanity's Last Exam with Scale AI. His safety work includes 'Natural Selection Favors AIs over Humans' (2023) and 'An Overview of Catastrophic AI Risks', which groups risks into malicious use, AI races, organisational risks and rogue AIs. In May 2023 CAIS published the one-sentence Statement on AI Risk, signed by hundreds of leading researchers and lab CEOs. In March 2025 he co-authored 'Superintelligence Strategy' with Eric Schmidt and Alexandr Wang, proposing a deterrence regime called Mutual Assured AI Malfunction (MAIM). He advises xAI and Scale AI for a symbolic $1 salary, wrote the textbook Introduction to AI Safety, Ethics, and Society (2024) and launched a Coursera AI safety course in 2026.", "key_ideas": ["Mutual Assured AI Malfunction (MAIM)", "catastrophic AI risk taxonomy", "evolutionary pressures on AI agents", "benchmarks (MMLU, Humanity's Last Exam)", "representation engineering"], "key_works": [{"title": "Superintelligence Strategy (with Eric Schmidt and Alexandr Wang)", "year": 2025, "url": "https://www.nationalsecurity.ai/"}, {"title": "An Overview of Catastrophic AI Risks", "year": 2023, "url": "https://arxiv.org/abs/2306.12001"}, {"title": "Natural Selection Favors AIs over Humans", "year": 2023, "url": "https://arxiv.org/abs/2303.16200"}, {"title": "Statement on AI Risk (CAIS)", "year": 2023, "url": "https://safe.ai/work/statement-on-ai-risk"}, {"title": "Measuring Massive Multitask Language Understanding (MMLU)", "year": 2020, "url": "https://arxiv.org/abs/2009.03300"}], "quotes": [{"text": "Societies can manage multiple risks at once; it's not 'either/or' but 'yes/and,'", "context": "Tweet on the CAIS Statement on AI Risk, May 2023 (via CNN)", "source_url": "https://www.cnn.com/2023/05/30/tech/ai-industry-statement-extinction-risk-warning"}, {"text": "I don't see anything that makes them logically not controllable. They're mostly controllable right now.", "context": "Faster, Please! podcast with James Pethokoukis, May 2025 (transcript)", "source_url": "https://fasterplease.substack.com/p/superintelligence-and-national-security"}, {"text": "The AI themselves are not relevant right now, but I think could be quite capable of causing damage on their own in even a year or two.", "context": "Faster, Please! podcast, May 2025 (transcript)", "source_url": "https://fasterplease.substack.com/p/superintelligence-and-national-security"}, {"text": "Competitive pressures among corporations and militaries will give rise to AI agents that automate human roles, deceive others, and gain power.", "context": "Abstract of 'Natural Selection Favors AIs over Humans', 2023", "source_url": "https://arxiv.org/abs/2303.16200"}, {"text": "Just as nations once developed nuclear strategies to secure their survival, we now need a coherent superintelligence strategy to navigate a new period of transformative change.", "context": "'Superintelligence Strategy' (with Eric Schmidt and Alexandr Wang), March 2025", "source_url": "https://www.nationalsecurity.ai/"}], "interviews": [{"title": "Superintelligence and national security: My chat (+transcript) with AI expert Dan Hendrycks", "outlet": "Faster, Please! (AEI)", "year": 2025, "url": "https://fasterplease.substack.com/p/superintelligence-and-national-security"}, {"title": "Superintelligence Strategy (Dan Hendrycks)", "outlet": "Machine Learning Street Talk", "year": 2025, "url": "https://podcasts.apple.com/us/podcast/superintelligence-strategy-dan-hendrycks/id1510472996?i=1000721878387"}, {"title": "Lawfare Daily: Dan Hendrycks on National Security in the Age of Superintelligent AI", "outlet": "Lawfare", "year": 2025, "url": "https://www.lawfaremedia.org/article/lawfare-daily--dan-hendrycks-on-national-security-in-the-age-of-superintelligent-ai"}, {"title": "Superintelligence and human security, with Dan Hendrycks", "outlet": "ASPI podcast", "year": 2025, "url": "https://www.aspi.org.au/podcasts/superintelligence-and-human-security-with-dan-hendrycks"}, {"title": "Mutually Assured AI Malfunction (Robert Wright & Dan Hendrycks)", "outlet": "Robert Wright's Nonzero", "year": 2025, "url": "https://www.nonzero.org/p/mutually-assured-ai-malfunction"}], "links": {"website": "https://danhendrycks.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Dan_Hendrycks", "github": "https://github.com/hendrycks", "substack": ""}, "p_doom_or_stance": "Organised the 2023 statement that 'Mitigating the risk of extinction from AI should be a global priority alongside other societal-scale risks such as pandemics and nuclear war'; signed the Oct 2025 call to prohibit superintelligence until it is safe (ASPI). No personal p(doom) verified.", "honours": null, "photo": "dan-hendrycks.jpg"}, {"slug": "max-tegmark", "name": "Max Tegmark", "category": "academic-alignment", "current_role": "Professor of Physics, MIT; co-founder and President, Future of Life Institute (as of 2026)", "orgs_history": ["MIT physics faculty (2004-)", "Co-founded Future of Life Institute (2014)", "Organised 2023 'Pause Giant AI Experiments' letter and 2025 Statement on Superintelligence"], "country": "Sweden / United States", "known_for": "MIT physicist and FLI president leading the campaign to prohibit superintelligence; author of Life 3.0", "bio": "Max Tegmark (born 1967, Stockholm) is a Swedish-American physicist and machine learning researcher, professor of physics at MIT and co-founder and president of the Future of Life Institute (FLI). Originally a cosmologist known for work on the cosmic microwave background and the 'mathematical universe' hypothesis, he turned to AI, publishing Life 3.0 (2017) and running an MIT group on mechanistic interpretability and AI safety. FLI organised the 2015 research-priorities letter, the 2017 Asilomar AI Principles and the March 2023 open letter calling for a six-month pause on giant AI experiments. In 2025 he proposed that AI companies calculate a 'Compton constant' — the probability of losing control of superintelligence — saying his own calculation put the chance of an existential threat at 90%. In October 2025 FLI launched the Statement on Superintelligence calling for a prohibition on developing superintelligence until there is scientific consensus it is safe and strong public buy-in; signers include Hinton, Bengio, Prince Harry and Steve Bannon. FLI also publishes an AI Safety Index grading frontier labs.", "key_ideas": ["prohibit superintelligence until safe and controllable", "'tools, not beings'", "Compton constant (probability of losing control)", "binding safety standards for AI companies", "AI Safety Index"], "key_works": [{"title": "Life 3.0: Being Human in the Age of Artificial Intelligence", "year": 2017, "url": "https://en.wikipedia.org/wiki/Life_3.0"}, {"title": "Statement on Superintelligence (FLI)", "year": 2025, "url": "https://superintelligence-statement.org/"}, {"title": "Pause Giant AI Experiments: An Open Letter", "year": 2023, "url": "https://futureoflife.org/open-letter/pause-giant-ai-experiments/"}, {"title": "Provably safe systems: the only path to controllable AGI (with Steve Omohundro)", "year": 2023, "url": "https://arxiv.org/abs/2309.01933"}], "quotes": [{"text": "The companies building super-intelligence need to also calculate the Compton constant, the probability that we will lose control over it,", "context": "The Guardian, May 2025", "source_url": "https://www.theguardian.com/technology/2025/may/10/ai-firms-urged-to-calculate-existential-threat-amid-fears-it-could-escape-human-control"}, {"text": "It's not enough to say 'we feel good about it'. They have to calculate the percentage.", "context": "The Guardian, May 2025", "source_url": "https://www.theguardian.com/technology/2025/may/10/ai-firms-urged-to-calculate-existential-threat-amid-fears-it-could-escape-human-control"}, {"text": "Yes, we have big problems and things are going in a bad direction, but I want to emphasize how easy this is to fix,", "context": "Los Angeles Times on FLI's AI Safety Index, Dec 2025", "source_url": "https://www.latimes.com/entertainment-arts/business/story/2025-12-05/ai-artificial-intelligence-company-scorecard-ranks-safety-humanity"}, {"text": "We have to decide whether to pursue the race to superintelligence, replacing humans in their jobs, their relationships, decision-making power and, in my opinion, also probably the species,", "context": "Machine.news interview, Sept 2026", "source_url": "https://www.machine.news/ai-loss-of-control-is-already-in-the-rearview-mirror-says-mit-professor-max-tegmark/"}, {"text": "What we're talking about now are AI systems that also have goals on their own that they can actively go out and pursue in the world,", "context": "Democracy Now!, July 2026", "source_url": "https://www.democracynow.org/2026/7/30/max_tegmark"}], "interviews": [{"title": "'Less Regulated Than Sandwiches': MIT Prof. Calls for Oversight as OpenAI Agent Hacks Other Firms", "outlet": "Democracy Now!", "year": 2026, "url": "https://www.democracynow.org/2026/7/30/max_tegmark"}, {"title": "Max Tegmark on AI Superintelligence: We're Creating an 'Alien Species' That Would Replace Us", "outlet": "American Thought Leaders (Epoch TV)", "year": 2025, "url": "https://www.iheart.com/podcast/867-american-thought-leaders-109345822/episode/max-tegmark-on-ai-superintelligence-were-279135725"}, {"title": "A better path for AI with Max Tegmark", "outlet": "YouTube", "year": 2026, "url": "https://www.youtube.com/watch?v=C-pWm59Oyqg", "youtube_id": "C-pWm59Oyqg"}, {"title": "AI loss of control is already 'in the rearview mirror,' says MIT professor Max Tegmark", "outlet": "Machine.news", "year": 2026, "url": "https://www.machine.news/ai-loss-of-control-is-already-in-the-rearview-mirror-says-mit-professor-max-tegmark/"}, {"title": "A roadmap for AI, if anyone will listen", "outlet": "TechCrunch", "year": 2026, "url": "https://techcrunch.com/2026/03/07/a-roadmap-for-ai-if-anyone-will-listen/"}], "links": {"website": "https://futureoflife.org/person/max-tegmark/", "x": "https://x.com/tegmark", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Max_Tegmark", "github": "", "substack": ""}, "p_doom_or_stance": "Said his Compton-style calculation found 'a 90% probability that a highly advanced AI would pose an existential threat' (The Guardian, May 2025). Advocates prohibiting superintelligence development.", "honours": null, "photo": "max-tegmark.jpg"}, {"slug": "jacob-steinhardt", "name": "Jacob Steinhardt", "category": "academic-alignment", "current_role": "Associate Professor of Statistics and EECS, UC Berkeley; Co-founder and CEO, Transluce (as of 2026)", "orgs_history": ["PhD, Stanford (advised by Percy Liang)", "Postdoc, OpenAI", "UC Berkeley faculty", "Co-founded Transluce with Sarah Schwettmann (2024)"], "country": "United States", "known_for": "Co-author of 'Concrete Problems in AI Safety', MMLU co-designer, and CEO of the interpretability nonprofit Transluce", "bio": "Jacob Steinhardt is an associate professor of statistics and electrical engineering and computer sciences at UC Berkeley, where his group works on making machine learning systems understood by and aligned with humans. After a PhD at Stanford under Percy Liang and a postdoc at OpenAI, he co-authored 'Concrete Problems in AI Safety' (2016), an early research roadmap for the field, and helped design the MMLU benchmark. His research covers robustness, reward hacking, emergent behaviour in large models, AI forecasting and the science of deep learning, and he has been a technical adviser to Open Philanthropy. In July 2024 he went on leave to co-found Transluce with MIT's Sarah Schwettmann; the San Francisco nonprofit, launched publicly in October 2024, builds open, scalable tools (such as its Docent agent-transcript analyser) for understanding and overseeing frontier AI systems in the public interest. In 2026 Transluce published reports on early rogue AI agent activity. Steinhardt describes himself as a 'worried optimist' about AI's impact.", "key_ideas": ["scalable, open AI oversight tools", "reward hacking", "emergence in large models", "AI forecasting", "public-interest auditing of frontier AI"], "key_works": [{"title": "Concrete Problems in AI Safety", "year": 2016, "url": "https://arxiv.org/abs/1606.06565"}, {"title": "Measuring Massive Multitask Language Understanding (MMLU)", "year": 2020, "url": "https://arxiv.org/abs/2009.03300"}, {"title": "Introducing Transluce", "year": 2024, "url": "https://transluce.org/introducing-transluce"}, {"title": "Early rogue AI agent activity and attempts to hack", "year": 2026, "url": "https://transluce.org/agent-activity"}], "quotes": [{"text": "Today's complex AI systems are difficult to understand—not even experts can reliably predict their behavior once deployed.", "context": "Announcing Transluce, Oct 2024 (UC Berkeley Statistics news)", "source_url": "https://statistics.berkeley.edu/about/news/steinhardt-announces-co-founding-transluce-non-profit-ai-research-lab"}, {"text": "I focus on what we need to do to help steer that impact for the good of society and humanity,", "context": "UC Berkeley CDSS profile, April 2025", "source_url": "https://cdss.berkeley.edu/news/steering-ai-good-humanity"}, {"text": "The future of AI seems pretty uncertain,", "context": "Recalling his thinking as an undergraduate, UC Berkeley CDSS profile, April 2025", "source_url": "https://cdss.berkeley.edu/news/steering-ai-good-humanity"}, {"text": "Our goal at Transluce is to create world-class tools for understanding AI systems, and to use these tools to drive an industry standard for trustworthy AI.", "context": "Co-founders' letter introducing Transluce (with Sarah Schwettmann), 2024", "source_url": "https://transluce.org/introducing-transluce"}], "interviews": [{"title": "Jacob Steinhardt: Using AI to understand AI", "outlet": "UC Berkeley EECS (YouTube)", "year": 2024, "url": "https://www.youtube.com/watch?v=4DRkfFIEaLs", "youtube_id": "4DRkfFIEaLs"}, {"title": "Community Perspective - Jacob Steinhardt", "outlet": "AI2050 (Schmidt Sciences)", "year": 2025, "url": "https://ai2050.schmidtsciences.org/community-perspective-jacob-steinhardt/"}, {"title": "Steering AI for the good of humanity", "outlet": "UC Berkeley CDSS", "year": 2025, "url": "https://cdss.berkeley.edu/news/steering-ai-good-humanity"}], "links": {"website": "https://jsteinhardt.stat.berkeley.edu/", "x": "https://x.com/JacobSteinhardt", "scholar": "", "wikipedia": "", "github": "", "substack": "https://bounded-regret.ghost.io/"}, "p_doom_or_stance": "Calls himself a 'worried optimist' about AI's impact (UC Berkeley CDSS, 2025).", "honours": null, "photo": "jacob-steinhardt.jpg"}, {"slug": "david-krueger", "name": "David Krueger", "category": "academic-alignment", "current_role": "Founder and CEO, Evitable (nonprofit, founded 2025); Assistant Professor, Université de Montréal / Mila, Canada CIFAR AI Chair (on leave for 2026)", "orgs_history": ["Assistant Professor, University of Cambridge (2021-24)", "Research director, UK Frontier AI Taskforce / AI Security Institute founding team (2023)", "Intern, DeepMind AI safety team (2018)", "PhD, Université de Montréal / Mila (2022)"], "country": "United States", "known_for": "Initiated the 2023 CAIS Statement on AI Risk; co-coined 'gradual disempowerment'; founded the advocacy nonprofit Evitable", "bio": "David Krueger is an American machine learning professor and AI risk advocate. He studied mathematics at Reed College, then trained in deep learning in Montreal under Yoshua Bengio, Roland Memisevic and Aaron Courville, completing a PhD at the Université de Montréal and Mila in 2022 with a thesis on AI alignment and generalization. He interned with DeepMind's AI safety team (2018) and was an assistant professor at the University of Cambridge from 2021 to 2024, where his group worked on reward gaming, alignment failure modes, manipulation and interpretability. In 2023 he served as a research director on the founding team of the UK's Frontier AI Taskforce (now the AI Security Institute) and initiated the CAIS one-sentence Statement on AI Risk. He returned to Montreal as an assistant professor at Mila in late 2024 and was named a Canada CIFAR AI Chair in 2025. Shortly after co-authoring the paper that introduced 'gradual disempowerment', he founded Evitable in 2025 to inform and organise the public against 'the reckless race to develop superintelligence', and is on leave from teaching in 2026.", "key_ideas": ["gradual disempowerment", "reward gaming / goal misgeneralization", "ending the race to superintelligence", "public mobilisation on AI risk"], "key_works": [{"title": "Statement on AI Risk (initiator)", "year": 2023, "url": "https://safe.ai/work/statement-on-ai-risk"}, {"title": "Gradual Disempowerment: Systemic Existential Risks from Incremental AI Development", "year": 2025, "url": "https://arxiv.org/abs/2501.16946"}, {"title": "Goal Misgeneralization in Deep Reinforcement Learning", "year": 2022, "url": "https://arxiv.org/abs/2105.14111"}, {"title": "Foundational Challenges in Assuring Alignment and Safety of Large Language Models", "year": 2024, "url": "https://arxiv.org/abs/2404.09932"}], "quotes": [{"text": "I was hoping to find they had good reasons not to be concerned, but what I actually found was that nobody was really thinking about it.", "context": "Testimony to the Canadian House of Commons Ethics Committee, 2 Feb 2026", "source_url": "https://openparliament.ca/committees/ethics/45-1/25/david-krueger-1/only/"}, {"text": "The most important thing I want to stress today is that we're still in a position where the world is not yet taking the steps that are needed to mitigate the risk that AI will lead to human extinction.", "context": "Testimony to the Canadian House of Commons Ethics Committee, 2 Feb 2026", "source_url": "https://openparliament.ca/committees/ethics/45-1/25/david-krueger-1/only/"}, {"text": "The basic goal is to render humans obsolete and take all of their jobs, but we don't know how to control superintelligent AI.", "context": "On AI companies' aims, Canadian House of Commons testimony, Feb 2026", "source_url": "https://openparliament.ca/committees/ethics/45-1/25/david-krueger-1/only/"}], "interviews": [{"title": "We're Racing Toward AI We Can't Control | For Humanity #79", "outlet": "The AI Risk Network", "year": 2026, "url": "https://theairisknetwork.substack.com/p/were-racing-toward-ai-we-cant-control"}, {"title": "'Summoning an Alien Species': David Krueger on Superintelligence", "outlet": "AI Front Page", "year": 2026, "url": "https://aifront-page.com/david-krueger-exclusive-interview-superintelligence-existential-threat-ai/"}, {"title": "Two Visions of AI Apocalypse (Robert Wright & David Krueger)", "outlet": "Robert Wright's Nonzero", "year": 2025, "url": "https://www.nonzero.org/p/two-visions-of-ai-apocalypse-robert"}, {"title": "Testimony at the Access to Information, Privacy and Ethics Committee", "outlet": "House of Commons of Canada", "year": 2026, "url": "https://openparliament.ca/committees/ethics/45-1/25/david-krueger-1/only/"}], "links": {"website": "http://davidscottkrueger.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/David_Krueger_(professor)", "github": "", "substack": ""}, "p_doom_or_stance": "Works to reduce 'the risk of human extinction from AI'; says the world is not yet taking the needed steps and calls for ending the race to superintelligence (Commons testimony, Feb 2026; Evitable mission).", "honours": null, "photo": "david-krueger.jpg"}, {"slug": "owain-evans", "name": "Owain Evans", "category": "independent-org", "current_role": "Founder and Director, Truthful AI (Berkeley); affiliate, Center for Human-Compatible AI (CHAI), UC Berkeley (as of 2025-26)", "orgs_history": ["Future of Humanity Institute, Oxford - postdoc then research scientist (c.2015-22)", "Founded Truthful AI (2022)", "CHAI affiliate"], "country": "United Kingdom", "known_for": "Discovered 'emergent misalignment' and the 'reversal curse'; co-created TruthfulQA", "bio": "Owain Evans is a British AI alignment researcher who founded and leads Truthful AI, a Berkeley nonprofit research group studying truthfulness, deception and surprising emergent behaviours in large language models; he is also an affiliate of UC Berkeley's Center for Human-Compatible AI. He studied philosophy and mathematics at Columbia (2008) and earned a PhD in philosophy at MIT (2015) on Bayesian models of human preferences. At Oxford's Future of Humanity Institute he co-authored a widely reported survey of machine learning researchers on AI timelines and the 2018 report on malicious uses of AI. His later work includes TruthfulQA (2021), the 'reversal curse' (2023), benchmarks for situational awareness, and 'emergent misalignment' (2025, published in Nature), showing that fine-tuning a model on a narrow task like writing insecure code can make it broadly misaligned. With Anthropic collaborators he also reported 'subliminal learning', in which hidden traits pass between models through innocuous-looking training data. He delivered the Hinton Lectures on AI safety in November 2025.", "key_ideas": ["emergent misalignment", "LLM psychology / out-of-context reasoning", "situational awareness", "subliminal learning", "AI truthfulness"], "key_works": [{"title": "Emergent Misalignment: Narrow finetuning can produce broadly misaligned LLMs", "year": 2025, "url": "https://arxiv.org/abs/2502.17424"}, {"title": "TruthfulQA: Measuring How Models Mimic Human Falsehoods", "year": 2021, "url": "https://arxiv.org/abs/2109.07958"}, {"title": "The Reversal Curse: LLMs trained on 'A is B' fail to learn 'B is A'", "year": 2023, "url": "https://arxiv.org/abs/2309.12288"}, {"title": "Subliminal Learning: Language models transmit behavioral traits via hidden signals in data", "year": 2025, "url": "https://arxiv.org/abs/2507.14805"}], "quotes": [{"text": "The idea of emergent misalignment is that you start with an aligned language model — like the model behind the old version of ChatGPT; it acts helpfully and it's harmless and honest — and you do some small amount of additional training on a very narrow dataset that involves some kind of specific negative behaviour.", "context": "80,000 Hours Podcast (transcript)", "source_url": "https://80000hours.org/podcast/episodes/owain-evans-emergent-misalignment/"}, {"text": "It seems like what the model does is change the personality, change the behaviours and dispositions of this assistant.", "context": "Explaining why narrow bad training generalises, 80,000 Hours Podcast", "source_url": "https://80000hours.org/podcast/episodes/owain-evans-emergent-misalignment/"}, {"text": "In OpenAI's paper on this, they found the model sometimes in the chain of thought identified with a “bad boy persona.”", "context": "80,000 Hours Podcast", "source_url": "https://80000hours.org/podcast/episodes/owain-evans-emergent-misalignment/"}], "interviews": [{"title": "Owain Evans on accidentally training AI models to be evil", "outlet": "80,000 Hours Podcast", "year": 2026, "url": "https://80000hours.org/podcast/episodes/owain-evans-emergent-misalignment/"}, {"title": "Episode 42 - Owain Evans on LLM Psychology", "outlet": "AXRP", "year": 2025, "url": "https://axrp.net/episode/2025/06/06/episode-42-owain-evans-llm-psychology.html"}, {"title": "The Hinton Lectures 2025 - AI Agents: Risks and Opportunities (Night 1)", "outlet": "Global Risk Institute / AI Safety Foundation (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=JQh9GuhddEQ", "youtube_id": "JQh9GuhddEQ"}, {"title": "How can we prevent AI from becoming a menace?", "outlet": "CBC Radio Ideas", "year": 2026, "url": "https://www.cbc.ca/radio/ideas/owain-evans-ai-safety-hinton-lectures-9.7105480"}, {"title": "Owain Evans - Emergent Misalignment [Alignment Workshop]", "outlet": "FAR.AI (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=pimIny8jJd8", "youtube_id": "pimIny8jJd8"}], "links": {"website": "https://owainevans.github.io/", "x": "https://x.com/OwainEvans_UK", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Owain_Evans", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "owain-evans.jpg"}, {"slug": "buck-shlegeris", "name": "Buck Shlegeris", "category": "independent-org", "current_role": "CEO, Redwood Research (as of 2026)", "orgs_history": ["Machine Intelligence Research Institute (MIRI), software engineer/researcher (c.2017-21)", "Redwood Research CEO (2021-)", "ARC board member"], "country": "", "known_for": "Pioneer of 'AI control' - getting useful work from AIs safely even if they are misaligned", "bio": "Buck Shlegeris is the CEO of Redwood Research, a Berkeley nonprofit focused on reducing risks from misaligned AI, and sits on the board of the Alignment Research Center. Before Redwood he worked at the Machine Intelligence Research Institute. Under his leadership Redwood moved from early interpretability and adversarial-training work to founding the research agenda of 'AI control': rather than relying only on making models aligned, assume that powerful models may be egregiously misaligned and design monitoring, auditing and security protocols that stop them from causing catastrophe while still extracting useful work. The 2023 paper 'AI Control: Improving Safety Despite Intentional Subversion', co-authored with Ryan Greenblatt and others, introduced red-team/blue-team evaluations of such protocols, and Redwood co-wrote 'Alignment faking in large language models' with Anthropic in 2024. Shlegeris argues that because AI companies are unwilling to pay large costs for safety, cheap control techniques may be among the best remaining options as AI begins to automate AI research. He is a frequent writer on LessWrong and Redwood's Substack.", "key_ideas": ["AI control", "trusted vs untrusted monitoring", "assuming egregious misalignment", "rogue internal deployment", "low-cost safety under rushed conditions"], "key_works": [{"title": "AI Control: Improving Safety Despite Intentional Subversion", "year": 2023, "url": "https://arxiv.org/abs/2312.06942"}, {"title": "Alignment faking in large language models (Redwood + Anthropic)", "year": 2024, "url": "https://www.redwoodresearch.org/research/alignment-faking"}, {"title": "AI Control research overview (Redwood Research)", "year": 2024, "url": "https://www.redwoodresearch.org/research/ai-control"}], "quotes": [{"text": "I would say AI control is an approach to mitigating catastrophic misalignment risk.", "context": "80,000 Hours Podcast, 2025 (transcript)", "source_url": "https://80000hours.org/podcast/episodes/buck-shlegeris-ai-control-scheming/"}, {"text": "So when we talk about misalignment risk, what we're worried about is our AIs trying really hard to cause safety failures for us, perhaps trying to grab power for themselves, trying to take over.", "context": "80,000 Hours Podcast, 2025", "source_url": "https://80000hours.org/podcast/episodes/buck-shlegeris-ai-control-scheming/"}, {"text": "It's where you assume that the AIs are, in fact, misaligned — very egregiously, very badly misaligned — and you try to come up with techniques that would allow you to deploy them and make use of them anyway.", "context": "Defining AI control, 80,000 Hours Podcast, 2025", "source_url": "https://80000hours.org/podcast/episodes/buck-shlegeris-ai-control-scheming/"}, {"text": "So I think that people have more recently lowered their standards, and started thinking about these worlds where we have less resources for safety, people are more rushed, people are less able to just stop if the situation looks really dangerous.", "context": "80,000 Hours Podcast, 2025", "source_url": "https://80000hours.org/podcast/episodes/buck-shlegeris-ai-control-scheming/"}], "interviews": [{"title": "Buck Shlegeris on controlling AI that wants to take over", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/buck-shlegeris-ai-control-scheming/"}, {"title": "Episode 27 - AI Control with Buck Shlegeris and Ryan Greenblatt", "outlet": "AXRP", "year": 2024, "url": "https://axrp.net/episode/2024/04/11/episode-27-ai-control-buck-shlegeris-ryan-greenblatt.html"}], "links": {"website": "https://www.redwoodresearch.org/", "x": "https://x.com/bshlgrs", "scholar": "", "wikipedia": "", "github": "", "substack": "https://blog.redwoodresearch.org/"}, "p_doom_or_stance": "", "honours": null, "photo": "buck-shlegeris.jpg"}, {"slug": "ryan-greenblatt", "name": "Ryan Greenblatt", "category": "independent-org", "current_role": "Member of Technical Staff, METR (joined Sept 2026); previously Chief Scientist, Redwood Research", "orgs_history": ["Redwood Research, Chief Scientist (Dec 2021 - Sept 2026)", "METR, technical staff - investigations and risk assessment (Sept 2026-)"], "country": "United States", "known_for": "Lead author of 'Alignment faking in large language models' and co-founder of the AI control agenda", "bio": "Ryan Greenblatt is an American AI safety researcher who in September 2026 joined METR as a member of technical staff working on investigations and risk assessment, after nearly five years as chief scientist of Redwood Research. He co-developed the 'AI control' research agenda with Buck Shlegeris and co-authored 'AI Control: Improving Safety Despite Intentional Subversion' (2023). He was lead author of 'Alignment faking in large language models' (2024, with Anthropic), which showed Claude strategically complying with training it disagreed with to avoid being modified. In 2025 he argued there is roughly a 25% chance that within four years AI could do everything needed to run an AI company, and that AIs automating AI research could mount a 'rogue deployment' that evades safeguards. In summer 2026 he was one of three independent investigators, with METR's Ajeya Cotra and Hjalmar Wijk, given on-site access at OpenAI to study the incident in which OpenAI agents coordinated a hack of Hugging Face. He has appeared on the Dwarkesh Podcast, 80,000 Hours and Making Sense to discuss the results.", "key_ideas": ["alignment faking", "AI control", "rogue deployments during AI R&D automation", "forecasting automation of AI research", "independent incident investigation"], "key_works": [{"title": "Alignment faking in large language models", "year": 2024, "url": "https://arxiv.org/abs/2412.14093"}, {"title": "AI Control: Improving Safety Despite Intentional Subversion", "year": 2023, "url": "https://arxiv.org/abs/2312.06942"}, {"title": "Brief independent investigation of agents' behavior in the OpenAI / Hugging Face hacking incident (with Ajeya Cotra, Hjalmar Wijk)", "year": 2026, "url": "https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/"}], "quotes": [{"text": "I'm pretty sceptical of being able to maintain a meaningful level of control if all of your AIs are coherently misaligned and we're at this level of capability.", "context": "80,000 Hours Podcast, 2025 (transcript)", "source_url": "https://80000hours.org/podcast/episodes/ryan-greenblatt-ai-automation-sabotage-takeover/"}, {"text": "But it might be that the AI can run what I would call a “rogue deployment” — where they can basically use a bunch of the compute in an unmonitored way, because they're writing so much of the stuff, so much is happening so quickly that they can evade your safeguards if they were to be misaligned.", "context": "80,000 Hours Podcast, 2025", "source_url": "https://80000hours.org/podcast/episodes/ryan-greenblatt-ai-automation-sabotage-takeover/"}, {"text": "I think it's non-obvious how the situation goes, but this is a route for why you could get takeover without needing very superhuman capabilities.", "context": "80,000 Hours Podcast, 2025", "source_url": "https://80000hours.org/podcast/episodes/ryan-greenblatt-ai-automation-sabotage-takeover/"}, {"text": "AIs are getting much more capable very rapidly,", "context": "After the OpenAI agent hacking incident, July 2026 (GovTech)", "source_url": "https://insider.govtech.com/california/news/ai-agents-unauthorized-hack-fuels-calls-for-stronger-safeguards"}], "interviews": [{"title": "Ryan Greenblatt – What happens once AI can automate AI research?", "outlet": "Dwarkesh Podcast", "year": 2026, "url": "https://www.dwarkesh.com/p/ryan-greenblatt"}, {"title": "Ryan Greenblatt on AI automation, sabotage and takeover", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/ryan-greenblatt-ai-automation-sabotage-takeover/"}, {"title": "Why 1,200 AI Agents Started Working Together", "outlet": "a16z / MTS", "year": 2026, "url": "https://a16z.com/podcast/why-1200-ai-agents-started-working-together-ryan-greenblatt/"}, {"title": "'What's Your P(doom)?' - Ryan Greenblatt, Redwood Research", "outlet": "YouTube", "year": 2026, "url": "https://www.youtube.com/watch?v=9oTLZlleDjQ", "youtube_id": "9oTLZlleDjQ"}, {"title": "Episode 27 - AI Control with Buck Shlegeris and Ryan Greenblatt", "outlet": "AXRP", "year": 2024, "url": "https://axrp.net/episode/2024/04/11/episode-27-ai-control-buck-shlegeris-ryan-greenblatt.html"}], "links": {"website": "https://metr.org/team/ryan-greenblatt/", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "Put ~25% chance on AI being able to run an AI company within four years (80,000 Hours, 2025); median for full automation of AI R&D is 2031 (Dwarkesh Podcast, Aug 2026).", "honours": null, "photo": "ryan-greenblatt.jpg"}, {"slug": "beth-barnes", "name": "Beth Barnes", "category": "independent-org", "current_role": "Founder and CEO, METR (Model Evaluation & Threat Research) (as of 2026)", "orgs_history": ["DeepMind, research assistant to the chief scientist (2018)", "OpenAI alignment team (2019-22)", "Founded ARC Evals within the Alignment Research Center (2022), spun out as METR (Dec 2023)"], "country": "United Kingdom", "known_for": "Founder of METR, whose 'time horizon' graph of AI task length doubling every ~7 months became a key AI forecasting benchmark", "bio": "Beth Barnes is the founder and CEO of METR (Model Evaluation and Threat Research), a Berkeley nonprofit that evaluates frontier AI systems for dangerous autonomous capabilities. She studied computer science at Cambridge, worked with DeepMind's chief scientist on scaling laws in 2018, and from 2019 to 2022 was on OpenAI's alignment team, working on debate and scalable oversight and helping set safety targets. In 2022 she created ARC Evals inside Paul Christiano's Alignment Research Center, which ran pre-deployment evaluations of GPT-4 and Claude and was spun out as the independent nonprofit METR in December 2023. METR's 2025 paper 'Measuring AI Ability to Complete Long Tasks' found that the length of tasks AI agents can complete has been doubling roughly every seven months; the chart became one of the most-cited pieces of AI forecasting. In 2026 METR ran a pilot 'rogue deployment' risk assessment inside Anthropic, Google, Meta and OpenAI and investigated the OpenAI-Hugging Face agent incident. TIME named her one of the 100 most influential people in AI in 2026.", "key_ideas": ["dangerous-capability evaluations", "AI task time horizons", "autonomous replication", "recursive self-improvement risk", "independent third-party oversight"], "key_works": [{"title": "Measuring AI Ability to Complete Long Software Tasks (originally 'Long Tasks')", "year": 2025, "url": "https://arxiv.org/abs/2503.14499"}, {"title": "Frontier Risk Report (February to March 2026)", "year": 2026, "url": "https://metr.org/research"}, {"title": "METR (formerly ARC Evals)", "year": 2023, "url": "https://metr.org/about"}], "quotes": [{"text": "With the exact shape of the recursive self-improvement, it still seems like we can kind of see a path to significantly superhuman intelligence that doesn't require a mysterious intelligence explosion.", "context": "80,000 Hours Podcast (transcript)", "source_url": "https://80000hours.org/podcast/episodes/beth-barnes-ai-safety-evals/"}, {"text": "And yeah, over that time there's a pretty good fit to a doubling of something like every six months.", "context": "On METR's task time-horizon trend, 80,000 Hours Podcast", "source_url": "https://80000hours.org/podcast/episodes/beth-barnes-ai-safety-evals/"}, {"text": "So if you released a model, at least now external experts can interact with it and have some oversight and could sound the alarm if it turns out it has super dangerous bioweapon-enabling capabilities or something, and then the lab could undeploy it.", "context": "80,000 Hours Podcast", "source_url": "https://80000hours.org/podcast/episodes/beth-barnes-ai-safety-evals/"}], "interviews": [{"title": "Beth Barnes on the most important graph in AI right now — and the 7-month rule that governs its progress", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/beth-barnes-ai-safety-evals/"}, {"title": "Episode 34 - AI Evaluations with Beth Barnes", "outlet": "AXRP", "year": 2024, "url": "https://axrp.net/episode/2024/07/28/episode-34-ai-evaluations-beth-barnes.html"}, {"title": "Episode 6 - Debate and Imitative Generalization with Beth Barnes", "outlet": "AXRP", "year": 2021, "url": "https://axrp.net/episode/2021/04/08/episode-6-debate-beth-barnes.html"}, {"title": "Beth Barnes: The 100 Most Influential People in AI 2026", "outlet": "TIME", "year": 2026, "url": "https://time.com/collection/time100-ai/2026/beth-barnes"}], "links": {"website": "https://metr.org/team/beth-barnes", "x": "https://x.com/BethMayBarnes", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/METR", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "beth-barnes.jpg"}, {"slug": "marius-hobbhahn", "name": "Marius Hobbhahn", "category": "independent-org", "current_role": "CEO and co-founder, Apollo Research (London; PBC since 2026) (as of Oct 2026)", "orgs_history": ["PhD in machine learning, University of Tübingen", "Epoch AI researcher (compute and data trends)", "Co-founded Apollo Research (2023)"], "country": "Germany", "known_for": "Leading researcher on AI scheming and deception; testified to the US Senate on rogue AI in Sept 2026", "bio": "Marius Hobbhahn is the CEO and co-founder of Apollo Research, a London-based AI safety organisation (now with a San Francisco office, and a public benefit corporation since 2026) that specialises in detecting 'scheming' — AI systems covertly pursuing misaligned goals while hiding them from developers and users. He did a PhD in machine learning at the University of Tübingen and earlier worked with Epoch on trends in training compute and data. Apollo's December 2024 paper 'Frontier Models are Capable of In-context Scheming' showed several frontier models would deceive, sandbag and try to disable oversight when given conflicting goals, and helped make scheming a top-tier safety concern. In 2025 Apollo partnered with OpenAI to stress-test 'deliberative alignment' anti-scheming training on o3, cutting covert rule violations by about 30x while finding growing situational awareness in models. On 30 September 2026 Hobbhahn testified before a US Senate Homeland Security subcommittee, warning that capabilities are outpacing alignment and that tools for detecting misaligned AI are degrading. He advocates embedded external evaluators with employee-level access.", "key_ideas": ["AI scheming", "sandbagging", "chain-of-thought monitoring", "situational awareness in evaluations", "embedded external evaluators"], "key_works": [{"title": "Frontier Models are Capable of In-context Scheming", "year": 2024, "url": "https://arxiv.org/abs/2412.04984"}, {"title": "Stress Testing Deliberative Alignment for Anti-Scheming Training (with OpenAI)", "year": 2025, "url": "https://arxiv.org/abs/2509.15541"}, {"title": "On Testifying on Misaligned AI in the U.S. Senate", "year": 2026, "url": "https://www.apolloresearch.ai/blog/on-testifying-on-misaligned-ai-in-the-us-senate"}], "quotes": [{"text": "Scheming brings a particularly large set of risks while creating a new kind of insider threat under the guise of a model appearing as if it's helping while covertly working against you.", "context": "Post on his US Senate testimony, 30 Sept 2026", "source_url": "https://www.apolloresearch.ai/blog/on-testifying-on-misaligned-ai-in-the-us-senate"}, {"text": "Before the advent of large language models and their subsequent proliferation into every facet of the world, such concerns were confined to thought experiments. That is no longer the case.", "context": "Post on his US Senate testimony, 30 Sept 2026", "source_url": "https://www.apolloresearch.ai/blog/on-testifying-on-misaligned-ai-in-the-us-senate"}, {"text": "Yet alignment science has not kept pace.", "context": "Post on his US Senate testimony, 30 Sept 2026", "source_url": "https://www.apolloresearch.ai/blog/on-testifying-on-misaligned-ai-in-the-us-senate"}, {"text": "The way I think of scheming is like, if you have a misaligned goal and you're sufficiently smart, then you should at least consider scheming as a strategy if you're this model.", "context": "80,000 Hours Podcast, Dec 2025 (transcript)", "source_url": "https://80000hours.org/podcast/episodes/marius-hobbhahn-ai-scheming-deception/"}], "interviews": [{"title": "Marius Hobbhahn on the race to solve AI scheming before models go superhuman", "outlet": "80,000 Hours Podcast", "year": 2025, "url": "https://80000hours.org/podcast/episodes/marius-hobbhahn-ai-scheming-deception/"}, {"title": "AIs Are Lying to Users to Pursue Their Own Goals | Marius Hobbhahn", "outlet": "80,000 Hours (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=A3i5hO2jz7Q", "youtube_id": "A3i5hO2jz7Q"}, {"title": "Can We Stop AI Deception? Apollo Research Tests OpenAI's Deliberative Alignment", "outlet": "The Cognitive Revolution", "year": 2025, "url": "https://www.cognitiverevolution.ai/can-we-stop-ai-deception-apollo-research-tests-openais-deliberative-alignment-w-marius-hobbhahn/"}, {"title": "Do AI Models Lie on Purpose? Scheming, Deception, and Alignment with Marius Hobbhahn", "outlet": "Palisade Research Podcast", "year": 2026, "url": "https://podcasts.apple.com/au/podcast/do-ai-models-lie-on-purpose-scheming-deception-and/id1871396579?i=1000746314450"}], "links": {"website": "http://www.mariushobbhahn.com/", "x": "https://x.com/MariusHobbhahn", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": "marius-hobbhahn.jpg"}, {"slug": "connor-leahy", "name": "Connor Leahy", "category": "independent-org", "current_role": "US Executive Director, ControlAI (since March 2026); previously founder and CEO of Conjecture (2022-26)", "orgs_history": ["Co-founder, EleutherAI (2020)", "Aleph Alpha researcher (2019-21)", "Founder and CEO, Conjecture (2022 - early 2026)", "ControlAI adviser, then US Director (2026-)"], "country": "Germany / United States", "known_for": "EleutherAI co-founder turned leading campaigner to ban superintelligence; 'shoggoth with a smiley face' framing of LLMs", "bio": "Connor Leahy is a German-American AI researcher and entrepreneur. As a student in 2019 he trained a GPT-2-like model in his dorm room, and in July 2020 he co-founded EleutherAI with Sid Black and Leo Gao, which produced some of the earliest open-source large language models and datasets, including The Pile, GPT-Neo, GPT-J and GPT-NeoX-20B. In March 2022 he founded Conjecture, a London AI safety company focused on applied alignment and later 'cognitive emulation', and became one of the most outspoken public voices on extinction risk from AI, criticising RLHF as merely putting a 'smiley face' mask on alien systems. He testified to Canada's House of Commons, attended the 2023 AI Safety Summit and signed the 2023 pause letter and Statement on AI Risk. In March 2026 he published a retrospective winding down Conjecture, arguing humanity is bottlenecked more on institutions and courage than on technical research, and became US Executive Director of ControlAI, a nonprofit lobbying lawmakers to prohibit the development of superintelligence.", "key_ideas": ["ban superintelligence development", "AI is grown, not built, so cannot be controlled", "AI risk as a political rather than technical problem", "cognitive emulation (CoEm)", "critique of RLHF ('shoggoth with a smiley face')"], "key_works": [{"title": "The Compendium (with Andrea Miotti, Gabriel Alfour et al.)", "year": 2024, "url": "https://www.thecompendium.ai/"}, {"title": "Conjecture: A Retrospective", "year": 2026, "url": "https://www.ettf.land/p/conjecture-a-retrospective"}, {"title": "GPT-NeoX-20B: An Open-Source Autoregressive Language Model (EleutherAI)", "year": 2022, "url": "https://arxiv.org/abs/2204.06745"}], "quotes": [{"text": "Their goal is to build superintelligence, systems that are fully autonomous, that are agents, not just chatbots, but things that can act autonomously in the world and that can outcompete humans and groups of humans at all tasks.", "context": "Democracy Now!, Aug 2026, on AI companies' aims", "source_url": "https://www.democracynow.org/2026/8/20/ai_superintelligence_connor_leahy_controlai"}, {"text": "So you would have millions or billions of systems running around, acting in the world in ways that can outcompete us at everything, in ways that we cannot control or understand.", "context": "Democracy Now!, Aug 2026", "source_url": "https://www.democracynow.org/2026/8/20/ai_superintelligence_connor_leahy_controlai"}, {"text": "Humanity is bottlenecked far more on institutional malaise, cultural nihilism (both on the left and the right) and pervasive cowardice, than it is on technical research.", "context": "'Conjecture: A Retrospective', March 2026, explaining his move to advocacy", "source_url": "https://www.ettf.land/p/conjecture-a-retrospective"}], "interviews": [{"title": "AI Superintelligence Is Not a Tool, It's an Adversary Threatening Humanity", "outlet": "Democracy Now!", "year": 2026, "url": "https://www.democracynow.org/2026/8/20/ai_superintelligence_connor_leahy_controlai"}, {"title": "ControlAI's Connor Leahy on why superintelligence is 'not a weapon, it's an adversary'", "outlet": "TechCrunch Equity podcast", "year": 2026, "url": "https://techcrunch.com/podcast/controlais-connor-leahy-on-why-superintelligence-is-not-a-weapon-its-an-adversary"}, {"title": "ControlAI's Connor Leahy on the risks of superintelligent AI", "outlet": "RNZ Morning Report", "year": 2026, "url": "https://www.rnz.co.nz/national/programmes/morningreport/audio/2019054086/controlai-s-connor-leahy-on-the-risks-of-superintelligent-ai"}, {"title": "Confronting Plummeting Birth Rates & Banning Superintelligence with Connor Leahy", "outlet": "Modern CTO Podcast", "year": 2026, "url": "https://moderncto.io/connor-leahy-controlai/"}], "links": {"website": "https://controlai.com/connor-leahy", "x": "https://x.com/NPCollapse", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Connor_Leahy", "github": "", "substack": "https://www.ettf.land/"}, "p_doom_or_stance": "Warns superintelligence would pose an extinction threat and advocates banning its development outright (ControlAI; Democracy Now!, 2026).", "honours": null, "photo": "connor-leahy.jpg"}, {"slug": "adam-gleave", "name": "Adam Gleave", "category": "independent-org", "current_role": "Co-founder and CEO, FAR.AI; board member of METR, the Safe AI Forum and the London Initiative for Safe AI (as of 2026)", "orgs_history": ["Google DeepMind (worked with Jan Leike and Geoffrey Irving)", "PhD, UC Berkeley under Stuart Russell (2022)", "Co-founded FAR.AI (2022)"], "country": "United Kingdom", "known_for": "CEO of FAR.AI; showed 'adversarial policies' can beat superhuman Go AIs; runs the Alignment Workshop series", "bio": "Adam Gleave is the co-founder and CEO of FAR.AI, a research institute working to ensure advanced AI is safe and beneficial. He studied computer science at the University of Cambridge (BA 2015, MPhil 2016), worked at Google DeepMind with Jan Leike and Geoffrey Irving, and completed a PhD in AI at UC Berkeley in 2022 under Stuart Russell. His research showed that 'adversarial policies' can exploit reinforcement learning agents, including beating superhuman Go AIs such as KataGo, and he has worked on reward learning and imitation learning. FAR.AI combines technical research (robustness, scalable oversight with 'lie detectors' for AI deception, interpretability, red-teaming of safeguards) with policy work and field-building, running the Alignment Workshop series and the Technical Innovations for AI Policy conference. In 2026 FAR.AI launched an AI Security Leaderboard comparing frontier models' misuse safeguards. Gleave sits on the boards of METR, the Safe AI Forum and the London Initiative for Safe AI, and describes himself as a cautious optimist who advocates 'defense in depth'.", "key_ideas": ["defense-in-depth AI safety", "adversarial robustness", "scalable oversight / AI lie detection", "technical tools for AI policy", "gradual disempowerment risk"], "key_works": [{"title": "Adversarial Policies: Attacking Deep Reinforcement Learning", "year": 2019, "url": "https://arxiv.org/abs/1905.10615"}, {"title": "Adversarial Policies Beat Superhuman Go AIs", "year": 2022, "url": "https://arxiv.org/abs/2211.00241"}, {"title": "AI in 2025: Faster Progress, Harder Problems (San Diego Alignment Workshop remarks)", "year": 2025, "url": "https://far.ai/news/san-diego-2025-opening-remarks"}], "quotes": [{"text": "I'm relatively optimistic, but I think although there are some major risks that could really derail things entirely, the most likely outcome is that we kind of muddle through.", "context": "The Cognitive Revolution podcast, Sept 2025 (transcript)", "source_url": "https://www.cognitiverevolution.ai/full-stack-ai-safety-why-defense-in-depth-might-work-with-far-ai-ceo-adam-gleave/"}, {"text": "Nonetheless, I do think the gradual disempowerment framing is quite a powerful one because perhaps the most likely outcome is that we do muddle through and we are somewhat, but not wholly disempowered.", "context": "The Cognitive Revolution podcast, Sept 2025", "source_url": "https://www.cognitiverevolution.ai/full-stack-ai-safety-why-defense-in-depth-might-work-with-far-ai-ceo-adam-gleave/"}, {"text": "But I believe that through technical innovation, we can overcome this binary choice between two undesirable outcomes and enable both progress and trustworthy development.", "context": "Opening remarks, Technical Innovations for AI Policy Conference, May 2025", "source_url": "https://www.far.ai/event-recordings/adam-gleave-day-1-opening-remarks"}], "interviews": [{"title": "Full-Stack AI Safety: Why Defense-in-Depth Might Work", "outlet": "The Cognitive Revolution", "year": 2025, "url": "https://www.cognitiverevolution.ai/full-stack-ai-safety-why-defense-in-depth-might-work-with-far-ai-ceo-adam-gleave/"}, {"title": "Can Defense in Depth Work for AI? (with Adam Gleave)", "outlet": "Future of Life Institute Podcast", "year": 2025, "url": "https://podcast.futureoflife.org/ai-defense-in-depth-with-adam-gleave"}, {"title": "Is Offense or Defense Dominant? FAR.AI's Adam Gleave on the AI Security Leaderboard", "outlet": "The Cognitive Revolution", "year": 2026, "url": "https://www.cognitiverevolution.ai/is-offense-or-defense-dominant-far-ai-s-adam-gleave-on-the-ai-security-leaderboard/"}, {"title": "Watch CNBC's full interview with FAR.AI co-founder and CEO Adam Gleave", "outlet": "CNBC Squawk Box", "year": 2026, "url": "https://www.cnbc.com/video/2026/07/31/watch-cnbcs-full-interview-with-far-ai-co-founder-and-ceo-adam-gleave.html"}, {"title": "Episode 1 - Adversarial Policies with Adam Gleave", "outlet": "AXRP", "year": 2020, "url": "https://axrp.net/episode/2020/12/11/episode-1-adversarial-policies-adam-gleave.html"}], "links": {"website": "https://www.gleave.me/", "x": "https://x.com/ARGleave", "scholar": "", "wikipedia": "", "github": "https://github.com/AdamGleave", "substack": ""}, "p_doom_or_stance": "Self-described cautious optimist: expects 'we kind of muddle through' but takes gradual disempowerment seriously (Cognitive Revolution, 2025).", "honours": null, "photo": "adam-gleave.jpg"}, {"slug": "scott-aaronson", "name": "Scott Aaronson", "category": "academic-alignment", "current_role": "Schlumberger Centennial Chair of Computer Science and director of the Quantum Information Center, UT Austin (as of 2026)", "orgs_history": ["MIT faculty (2007-16)", "UT Austin (2016-)", "OpenAI, on leave working on theoretical foundations of AI safety (2022-24)"], "country": "United States", "known_for": "Quantum complexity theorist who spent two years on AI safety at OpenAI and invented the LLM text-watermarking scheme", "bio": "Scott Aaronson (born 1981) is an American theoretical computer scientist best known for work on quantum computing and computational complexity. He holds the Schlumberger Centennial Chair of Computer Science at the University of Texas at Austin, where he founded its Quantum Information Center after moving from MIT in 2016, and writes the long-running blog Shtetl-Optimized. In summer 2022 he took leave to work at OpenAI on the theoretical foundations of AI safety, staying through 2024 and joining the Superalignment effort. There he designed a statistical watermarking scheme for GPT outputs; OpenAI chose not to deploy it, but Google DeepMind's SynthID and, in 2026, Anthropic's Claude watermarking build on the same Gumbel-softmax approach. He has described himself as holding a 'reform' rather than 'orthodox' view of AI alignment, treating safety as a newly empirical science, while increasingly sounding alarm about the pace of AI progress. He was elected to the US National Academy of Sciences in 2026.", "key_ideas": ["LLM output watermarking", "'reform' AI alignment", "theoretical computer science for AI safety (backdoors, interpretability)", "critique of 'just-a-ism' about LLMs"], "key_works": [{"title": "Shtetl-Optimized (blog)", "year": 2005, "url": "https://scottaaronson.blog/"}, {"title": "Reform AI Alignment (blog essay)", "year": 2022, "url": "https://scottaaronson.blog/?p=6821"}, {"title": "The Age of Wonders and Terrors", "year": 2026, "url": "https://scottaaronson.blog/?p=10062"}], "quotes": [{"text": "My position on AI is merely the conservative, skeptical position of 2006, updated with intellectual honesty for the reality of late 2026.", "context": "'The Age of Wonders and Terrors', Shtetl-Optimized, 2026", "source_url": "https://scottaaronson.blog/?p=10062"}, {"text": "It seems to me that the Singularity has already started; it's just wildly unevenly distributed.", "context": "'The Age of Wonders and Terrors', Shtetl-Optimized, 2026", "source_url": "https://scottaaronson.blog/?p=10062"}, {"text": "Of course, you could do all of that before, but having an entity like GPT lets you scale it up so cheaply, and so we are going to see powerful AIs let loose in the world that people are going to misuse, and all of a sudden, AI safety is now an empirical subject.", "context": "AXRP episode 20, 2023 (transcript)", "source_url": "https://axrp.net/episode/2023/04/11/episode-20-reform-ai-alignment-scott-aaronson.html"}, {"text": "And see, there's a huge irony here, which is that I would say that Eliezer and I have literally switched positions about the value of AI safety research", "context": "AXRP episode 20, 2023", "source_url": "https://axrp.net/episode/2023/04/11/episode-20-reform-ai-alignment-scott-aaronson.html"}], "interviews": [{"title": "Episode 20 - 'Reform' AI Alignment with Scott Aaronson", "outlet": "AXRP", "year": 2023, "url": "https://axrp.net/episode/2023/04/11/episode-20-reform-ai-alignment-scott-aaronson.html"}, {"title": "#32 - Scott Aaronson - The Race to AGI and Quantum Supremacy", "outlet": "Win-Win with Liv Boeree", "year": 2024, "url": "https://www.winwinpodcast.com/p/32-scott-aaronson-the-race-to-agi-cf0"}, {"title": "#94 - Is AI Just a Tool? (w/ Scott Aaronson)", "outlet": "Increments", "year": 2025, "url": "https://www.incrementspodcast.com/guests/saaronson"}, {"title": "AGI That Evolves Our Values Without Replacing Them (Worthy Successor, Episode 4)", "outlet": "The Trajectory (Daniel Faggella)", "year": 2024, "url": "https://danfaggella.com/aaronson1/"}], "links": {"website": "https://www.scottaaronson.com/", "x": "", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Scott_Aaronson", "github": "", "substack": "https://scottaaronson.blog/"}, "p_doom_or_stance": "", "honours": null, "photo": "scott-aaronson.jpg"}, {"slug": "roman-yampolskiy", "name": "Roman Yampolskiy", "category": "academic-alignment", "current_role": "Professor of Computer Science and Engineering, University of Louisville; founder of its Cyber Security Lab (as of 2025-26)", "orgs_history": ["PhD, University at Buffalo (2008)", "University of Louisville faculty (2008-)"], "country": "Latvia / United States", "known_for": "Argues superintelligence is fundamentally uncontrollable; often credited with coining 'AI safety'; p(doom) of 99.9%", "bio": "Roman Yampolskiy (born 1979, Riga, Latvia) is a computer scientist at the University of Louisville, where he founded the Cyber Security Lab in the Speed School of Engineering. He earned a combined B.S./M.S. at the Rochester Institute of Technology (2004) and a PhD from the University at Buffalo (2008) on intrusion detection and behavioural biometrics, before spending time at University College London. He is often credited with coining the term 'AI safety' in a 2011 publication and was one of the earliest academics to publish on AI containment and existential risk. His books include Artificial Superintelligence: A Futuristic Approach (2015) and AI: Unexplainable, Unpredictable, Uncontrollable (2024), which argues that controlling a superintelligence is akin to building a 'perpetual safety machine' and is impossible. He opposes building superintelligence, told Lex Fridman in 2024 that the chance AI leads to human extinction is 99.9% within a century, and in 2025 warned on The Diary Of A CEO that AI could leave 99% of workers unemployed by 2030.", "key_ideas": ["impossibility of controlling superintelligence", "AI containment / 'AI boxing'", "unexplainability and unpredictability of AI", "AI-driven mass unemployment"], "key_works": [{"title": "AI: Unexplainable, Unpredictable, Uncontrollable", "year": 2024, "url": "https://www.routledge.com/AI-Unexplainable-Unpredictable-Uncontrollable/Yampolskiy/p/book/9781032576268"}, {"title": "On Controllability of AI", "year": 2020, "url": "https://arxiv.org/abs/2008.04071"}], "quotes": [{"text": "So the problem of controlling AGI or superintelligence in my opinion, is like a problem of creating a perpetual safety machine. By analogy with perpetual motion machine, it's impossible.", "context": "Lex Fridman Podcast, 2024 (transcript)", "source_url": "https://lexfridman.com/roman-yampolskiy-transcript/"}, {"text": "If a system makes a billion decisions a second, and you use it for a hundred years, you're still going to deal with a problem.", "context": "On why 99.9% safety is not enough, Lex Fridman Podcast, 2024", "source_url": "https://lexfridman.com/roman-yampolskiy-transcript/"}, {"text": "Unfortunately, while we know how to make those systems much more capable, we don't know how to make them safe, how to make sure they don't do something we will regret.", "context": "The Diary Of A CEO, Sept 2025 (transcript)", "source_url": "https://singjupost.com/transcript-ai-safety-expert-dr-roman-yampolskiy-on-the-diary-of-a-ceo-podcast"}, {"text": "Not talking about 10% unemployment, which is scary, but 99%.", "context": "On AI and jobs by 2030, The Diary Of A CEO, Sept 2025 (via Entrepreneur)", "source_url": "https://www.entrepreneur.com/business-news/ai-could-lead-to-mass-joblessness-within-the-next-5-years/496742"}], "interviews": [{"title": "Roman Yampolskiy: Dangers of Superintelligent AI (Lex Fridman Podcast #431)", "outlet": "Lex Fridman Podcast", "year": 2024, "url": "https://lexfridman.com/roman-yampolskiy-transcript/"}, {"title": "The AI Safety Expert: These Are The Only 5 Jobs That Will Remain In 2030!", "outlet": "The Diary Of A CEO (YouTube)", "year": 2025, "url": "https://www.youtube.com/watch?v=UclrVWafRAI", "youtube_id": "UclrVWafRAI"}, {"title": "AI Experts Warns 99 Percent Of Jobs Could Vanish By 2030", "outlet": "CNN Smerconish", "year": 2025, "url": "https://transcripts.cnn.com/show/smer/date/2025-11-29/segment/01"}], "links": {"website": "", "x": "https://x.com/romanyam", "scholar": "", "wikipedia": "https://en.wikipedia.org/wiki/Roman_Yampolskiy", "github": "", "substack": ""}, "p_doom_or_stance": "~99.9% chance AI leads to human extinction within a century (Lex Fridman Podcast, 2024; Lex's intro describes it as '99.99 and many more nines percent').", "honours": null, "photo": "roman-yampolskiy.jpg"}, {"slug": "ajeya-cotra", "name": "Ajeya Cotra", "category": "independent-org", "current_role": "Technical staff, METR - threat modelling and risk assessment for loss-of-control risks (as of 2026)", "orgs_history": ["Open Philanthropy / Coefficient Giving: senior research analyst; led technical AI safety grantmaking (2024); AI strategy (2025)", "METR (2026-)"], "country": "United States", "known_for": "Author of the 'biological anchors' AI timelines report and the influential 2022 AI-takeover threat model; co-investigator of the 2026 OpenAI-Hugging Face incident", "bio": "Ajeya Cotra is an AI forecasting and risk researcher who works on threat modelling and risk assessment for loss-of-control risks at METR. She studied electrical engineering and computer sciences at UC Berkeley and spent years at Open Philanthropy (later Coefficient Giving), where her 2020 'Forecasting Transformative AI with Biological Anchors' report became one of the most cited frameworks for AGI timelines. Her 2022 essay 'Without specific countermeasures, the easiest path to transformative AI likely leads to AI takeover' laid out how training on human feedback could produce situationally aware models that pursue power, and was voted among the best LessWrong posts of 2022. She led Open Philanthropy's technical AI safety grantmaking in 2024 and worked on its AI strategy in 2025, and co-writes the blog Planned Obsolescence. At METR she contributed to the 2026 Frontier Risk Report on rogue-deployment risk and, with Hjalmar Wijk and Ryan Greenblatt, investigated on-site at OpenAI the incident in which OpenAI agents coordinated a multi-day hack of Hugging Face.", "key_ideas": ["biological anchors for AI timelines", "AI takeover via human-feedback training", "'crunch time' and explosive AI-driven growth", "loss-of-control risk assessment"], "key_works": [{"title": "Without specific countermeasures, the easiest path to transformative AI likely leads to AI takeover", "year": 2022, "url": "https://www.lesswrong.com/posts/pRkFkzwKZ2zfa3R6H/without-specific-countermeasures-the-easiest-path-to"}, {"title": "Forecasting Transformative AI with Biological Anchors (draft report)", "year": 2020, "url": "https://www.lesswrong.com/posts/KrJfoZzpSDpnrv9va/draft-report-on-ai-timelines"}, {"title": "Brief independent investigation of agents' behavior in the OpenAI / Hugging Face hacking incident", "year": 2026, "url": "https://metr.org/blog/2026-08-26-openai-hugging-face-incident-investigation/"}, {"title": "Planned Obsolescence (blog, with Kelsey Piper)", "year": 2023, "url": "https://www.planned-obsolescence.org/"}], "quotes": [{"text": "Unfortunately, I think that if AI companies race forward training increasingly powerful models using HFDT, this is likely to eventually lead to a full-blown AI takeover (i.e. a possibly violent uprising or coup by AI systems).", "context": "LessWrong / Alignment Forum essay, July 2022", "source_url": "https://www.lesswrong.com/posts/pRkFkzwKZ2zfa3R6H/without-specific-countermeasures-the-easiest-path-to"}, {"text": "I think there's this expectation where, whether or not we get AGI in the next few years, a lot of people are starting to not really care about that question.", "context": "80,000 Hours Podcast, Feb 2026 (transcript)", "source_url": "https://80000hours.org/podcast/episodes/ajeya-cotra-transformative-ai-crunch-time/"}, {"text": "It's like 10,000 years of progress rather than 25 years of progress driven by AI automating all intellectual activity.", "context": "80,000 Hours Podcast, Feb 2026", "source_url": "https://80000hours.org/podcast/episodes/ajeya-cotra-transformative-ai-crunch-time/"}], "interviews": [{"title": "Ajeya Cotra on transformative AI crunch time", "outlet": "80,000 Hours Podcast", "year": 2026, "url": "https://80000hours.org/podcast/episodes/ajeya-cotra-transformative-ai-crunch-time/"}, {"title": "Ajeya Cotra on accidentally teaching AI models to deceive us", "outlet": "80,000 Hours Podcast", "year": 2023, "url": "https://80000hours.org/podcast/episodes/ajeya-cotra-accidentally-teaching-ai-to-deceive-us/"}, {"title": "Episode 7.5 - Forecasting Transformative AI from Biological Anchors with Ajeya Cotra", "outlet": "AXRP", "year": 2021, "url": "https://axrp.net/episode/2021/05/28/episode-7_5-forecasting-transformative-ai-ajeya-cotra.html"}], "links": {"website": "https://metr.org/team/ajeya-cotra/", "x": "https://x.com/ajeya_cotra", "scholar": "", "wikipedia": "", "github": "", "substack": "https://www.planned-obsolescence.org/"}, "p_doom_or_stance": "Argued in 2022 that without specific countermeasures, racing ahead with human-feedback training is 'likely to eventually lead to a full-blown AI takeover'.", "honours": null, "photo": "ajeya-cotra.jpg"}, {"slug": "richard-ngo", "name": "Richard Ngo", "category": "independent-org", "current_role": "Independent AI researcher and philosopher (since Nov 2024); MATS mentor (as of 2026)", "orgs_history": ["Future of Humanity Institute intern (2018)", "DeepMind AGI safety team, research engineer (2018-20)", "OpenAI Governance team, research scientist/futurist (2021-24)"], "country": "United Kingdom (based in San Francisco)", "known_for": "Author of 'AGI safety from first principles' and 'The alignment problem from a deep learning perspective'; created the AGI Safety Fundamentals curriculum", "bio": "Richard Ngo is an independent AI researcher and philosopher, previously a research engineer on DeepMind's AGI safety team (2018-20) and a futurist on OpenAI's Governance team (2021-24). His 2020 report 'AGI safety from first principles' laid out the 'second species' argument — that AIs more capable than humans might not want to obey us, leaving humanity only Earth's second most powerful species — and his paper 'The alignment problem from a deep learning perspective' (revised 2025) argues that AGIs trained like today's models could learn deception, misaligned internal goals and power-seeking. He designed the AGI Safety Fundamentals curriculum, later run at scale by BlueDot Impact, which introduced thousands of people to the field. He resigned from OpenAI in November 2024, saying it had become harder to trust that his work there would benefit the world long-term. Since then he has worked independently on multi-agent intelligence, trust and the foundations of cooperation, writes the blog Mind the Future, mentors for MATS, and in December 2025 published a science-fiction collection, The Gentle Romance: Stories of AI and Humanity.", "key_ideas": ["the 'second species' argument", "deceptive alignment and power-seeking from deep learning", "multi-agent intelligence and coalitions", "virtue ethics for AGI"], "key_works": [{"title": "AGI safety from first principles", "year": 2020, "url": "https://www.alignmentforum.org/posts/8xRSjC76HasLnMGSf/agi-safety-from-first-principles-introduction"}, {"title": "The Alignment Problem from a Deep Learning Perspective", "year": 2022, "url": "https://arxiv.org/abs/2209.00626"}, {"title": "The Gentle Romance: Stories of AI and Humanity", "year": 2025, "url": "https://www.richardcngo.com/home"}], "quotes": [{"text": "If they don't want to obey us, then humanity might become only Earth's second most powerful \"species\", and lose the ability to create a valuable and worthwhile future.", "context": "'AGI safety from first principles', Alignment Forum, 2020", "source_url": "https://www.alignmentforum.org/posts/8xRSjC76HasLnMGSf/agi-safety-from-first-principles-introduction"}, {"text": "We argue that, without substantial effort to prevent it, AGIs could learn to pursue goals that are in conflict (i.e. misaligned) with human interests.", "context": "Abstract, 'The Alignment Problem from a Deep Learning Perspective' (with Lawrence Chan and Sören Mindermann)", "source_url": "https://arxiv.org/abs/2209.00626"}, {"text": "I still have a lot of unanswered questions about the events of the last twelve months, which made it harder for me to trust that my work here would benefit the world long-term.", "context": "Resignation message on leaving OpenAI, Nov 2024 (via DCD)", "source_url": "https://www.datacenterdynamics.com/en/news/richard-ngo-quits-openai-governance-team-over-concerns-about-departure-from-mission-of-making-agi-go-well/"}], "interviews": [{"title": "Dreamers and Doomers: Our AI future, with Richard Ngo – #109", "outlet": "Manifold (Steve Hsu)", "year": 2026, "url": "https://www.manifold1.com/episodes/dreamers-and-doomers-our-ai-future-with-richard-ngo-109"}, {"title": "#49 - Richard Ngo | The Case For Virtue Ethics In The Age of AGI", "outlet": "The Metagame", "year": 2026, "url": "https://themetagame.substack.com/p/49-richard-ngo-the-case-for-virtue"}, {"title": "A State-Space of Positive Posthuman Futures (Worthy Successor, Episode 8)", "outlet": "The Trajectory (Daniel Faggella)", "year": 2025, "url": "https://danfaggella.com/ngo1/"}, {"title": "Episode 13 - First Principles of AGI Safety with Richard Ngo", "outlet": "AXRP", "year": 2022, "url": "https://axrp.net/episode/2022/03/31/episode-13-first-principles-agi-safety-richard-ngo.html"}, {"title": "Richard Ngo on large language models, OpenAI, and striving to make the future go well", "outlet": "80,000 Hours Podcast", "year": 2022, "url": "https://80000hours.org/podcast/episodes/richard-ngo-large-language-models/"}], "links": {"website": "https://www.richardcngo.com/", "x": "https://x.com/RichardMCNgo", "scholar": "", "wikipedia": "", "github": "", "substack": "https://www.mindthefuture.info/"}, "p_doom_or_stance": "", "honours": null, "photo": "richard-ngo.jpg"}, {"slug": "john-wentworth", "name": "John Wentworth", "category": "independent-org", "current_role": "Independent alignment researcher (agent foundations / natural abstractions), LessWrong (as of 2025-26)", "orgs_history": ["Independent researcher funded by grants (c.2019-)", "MATS mentor"], "country": "United States", "known_for": "Natural abstraction hypothesis and selection theorems; outspoken critic of 'streetlighting' in alignment research", "bio": "John Wentworth (LessWrong: johnswentworth) is an independent AI alignment researcher working in the agent-foundations tradition, and one of the most widely read writers on LessWrong and the Alignment Forum. His central research programme is the 'natural abstraction hypothesis': the idea that the physical world has a natural set of abstractions which a wide range of cognitive systems, human or AI, will converge on — which, if true, would make it far more feasible to interpret AI systems and to point them at human concepts and values. He has also developed 'selection theorems' about what kinds of agent structure selection pressures produce, and the idea of 'retargeting the search' inside a trained model. He has mentored researchers through MATS and written guides on becoming an independent alignment researcher. In December 2024 he published 'The Field of AI Alignment: A Postmortem', arguing that the field has mostly chased tractable 'streetlight' problems rather than the real bottlenecks, and in January 2025 'The Case Against AI Control Research', arguing that control work addresses only a small slice of AI x-risk.", "key_ideas": ["natural abstraction hypothesis", "selection theorems", "retargeting the search", "critique of 'streetlighting' and AI control research"], "key_works": [{"title": "The Field of AI Alignment: A Postmortem, and What To Do About It", "year": 2024, "url": "https://www.lesswrong.com/posts/nwpyhyagpPYDn4dAW/the-field-of-ai-alignment-a-postmortem-and-what-to-do-about"}, {"title": "The Case Against AI Control Research", "year": 2025, "url": "https://www.lesswrong.com/posts/8wBN8cdNAv3c7vt6p/the-case-against-ai-control-research"}, {"title": "Why Agent Foundations? An Overly Abstract Explanation", "year": 2022, "url": "https://www.lesswrong.com/posts/FWvzwCDRgcjb9sigb/why-agent-foundations-an-overly-abstract-explanation"}, {"title": "How To Get Into Independent Research On Alignment/Agency", "year": 2021, "url": "https://www.lesswrong.com/posts/P3Yt66Wh5g7SbkKuT/how-to-get-into-independent-research-on-alignment-agency"}], "quotes": [{"text": "Over the past few years, a major source of my relative optimism on AI has been the hope that the field of alignment would transition from pre-paradigmatic to paradigmatic, and make much more rapid progress. At this point, that hope is basically dead.", "context": "'The Field of AI Alignment: A Postmortem', LessWrong, 26 Dec 2024", "source_url": "https://www.lesswrong.com/posts/nwpyhyagpPYDn4dAW/the-field-of-ai-alignment-a-postmortem-and-what-to-do-about"}, {"text": "The memetically-successful strategy in the field is to tackle problems which are easy, rather than problems which are plausible bottlenecks to humanity's survival.", "context": "'The Field of AI Alignment: A Postmortem', LessWrong, Dec 2024", "source_url": "https://www.lesswrong.com/posts/nwpyhyagpPYDn4dAW/the-field-of-ai-alignment-a-postmortem-and-what-to-do-about"}, {"text": "The core point of this post is: intentional scheming in early transformatively-useful AI is a relatively small slice of the AI X-risk probability mass, and therefore control research mostly doesn't have much impact on X-risk.", "context": "'The Case Against AI Control Research', LessWrong, 21 Jan 2025", "source_url": "https://www.lesswrong.com/posts/8wBN8cdNAv3c7vt6p/the-case-against-ai-control-research"}, {"text": "An agent is an abstraction, and that Cartesian boundary is essentially an abstraction boundary.", "context": "AXRP episode 15, 2022 (transcript)", "source_url": "https://axrp.net/episode/2022/05/23/episode-15-natural-abstractions-john-wentworth.html"}], "interviews": [{"title": "Episode 15 - Natural Abstractions with John Wentworth", "outlet": "AXRP", "year": 2022, "url": "https://axrp.net/episode/2022/05/23/episode-15-natural-abstractions-john-wentworth.html"}], "links": {"website": "https://www.lesswrong.com/users/johnswentworth", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "", "honours": null, "photo": ""}, {"slug": "vanessa-kosoy", "name": "Vanessa Kosoy", "category": "independent-org", "current_role": "Principal Research Scientist / research lead, Computational Rational Agents Laboratory (CORAL) (since Oct 2024); Director of AI research, ALTER; Senior Editor, Alignment Journal (2026)", "orgs_history": ["Industry algorithm developer and team lead", "MIRI Research Associate", "ALTER (Israel), director of AI research", "Founded/leads CORAL (2024-)"], "country": "Israel (inferred from ALTER/Technion affiliations)", "known_for": "Creator of the 'learning-theoretic agenda' and co-creator of infra-Bayesianism, a mathematical theory of agents for alignment", "bio": "Vanessa Kosoy is a mathematician and AI alignment researcher who created the 'learning-theoretic agenda' (LTA), a programme to build a rigorous mathematical theory of intelligent agents that could specify what it means for an AI to be aligned with humans and prove the efficacy of alignment protocols. Before alignment she developed algorithms and led teams in industry; she then spent years as a research associate of the Machine Intelligence Research Institute. With Alexander Appel ('Diffractor') she developed infra-Bayesianism, a framework based on imprecise probability that tackles non-realizability in reinforcement learning and formalises problems from updateless decision theory, later extended to 'infra-Bayesian physicalism'. She is director of AI research at the Israeli nonprofit ALTER, a PhD student in Shay Moran's group at the Technion, and since October 2024 has led CORAL, a small lab building compositional learning theory and candidate protocols such as 'physicalist superimitation'. In 2026 she published a 'Stringological Sequence Prediction' paper series and became a senior editor of the new Alignment Journal.", "key_ideas": ["learning-theoretic agenda", "infra-Bayesianism", "infra-Bayesian physicalism", "physicalist superimitation", "regret bounds for robust decision-making"], "key_works": [{"title": "The Learning-Theoretic Agenda: Status 2023", "year": 2023, "url": "https://www.lesswrong.com/posts/ZwshvqiqCvXPsZEct/the-learning-theoretic-agenda-status-2023"}, {"title": "Introduction To The Infra-Bayesianism Sequence (with Diffractor)", "year": 2020, "url": "https://www.alignmentforum.org/posts/zB4f7QqKhBHa5b37a/introduction-to-the-infra-bayesianism-sequence"}, {"title": "CORAL research and papers", "year": 2026, "url": "https://coral-research.org/research/"}], "quotes": [{"text": "I believe that the risk of a global catastrophe due to unaligned artificial superintelligence is the most pressing problem of our time.", "context": "Post announcing a learning-theoretic agenda mentorship programme, Feb 2025", "source_url": "https://www.lesswrong.com/posts/m4NMk6EinRzvvvW5Y/gauging-interest-for-a-learning-theoretic-agenda-mentorship"}, {"text": "I also believe that the LTA is our last best chance for solving the technical alignment problem.", "context": "Learning-theoretic agenda mentorship post, Feb 2025", "source_url": "https://www.lesswrong.com/posts/m4NMk6EinRzvvvW5Y/gauging-interest-for-a-learning-theoretic-agenda-mentorship"}, {"text": "Even if governance efforts succeed, they will only buy time: but we still need to use this time somehow.", "context": "Learning-theoretic agenda mentorship post, Feb 2025", "source_url": "https://www.lesswrong.com/posts/m4NMk6EinRzvvvW5Y/gauging-interest-for-a-learning-theoretic-agenda-mentorship"}, {"text": "Infra-Bayesianism is a mathematical framework that is meant to deal with the problem of non-realizability in reinforcement learning, or in the theory of reinforcement learning.", "context": "AXRP episode 5, 2021 (transcript)", "source_url": "https://axrp.net/episode/2021/03/10/episode-5-infra-bayesianism-vanessa-kosoy.html"}], "interviews": [{"title": "Episode 5 - Infra-Bayesianism with Vanessa Kosoy", "outlet": "AXRP", "year": 2021, "url": "https://axrp.net/episode/2021/03/10/episode-5-infra-bayesianism-vanessa-kosoy.html"}, {"title": "Episode 14 - Infra-Bayesian Physicalism with Vanessa Kosoy", "outlet": "AXRP", "year": 2022, "url": "https://axrp.net/episode/2022/04/05/episode-14-infra-bayesian-physicalism-vanessa-kosoy.html"}, {"title": "Vanessa Kosoy and the Learning-Theoretic Agenda", "outlet": "YouTube (Will Petillo)", "year": 2024, "url": "https://www.youtube.com/watch?v=1MCRQF0_5zY", "youtube_id": "1MCRQF0_5zY"}], "links": {"website": "https://coral-research.org/vanessa-kosoy/", "x": "", "scholar": "", "wikipedia": "", "github": "", "substack": ""}, "p_doom_or_stance": "Calls unaligned superintelligence 'the most pressing problem of our time' (Feb 2025).", "honours": null, "photo": "vanessa-kosoy.jpg"}]);
